class Solution {
    public int thirdMax(int[] nums){
        TreeSet<Integer> top=new TreeSet<>();
        for(int value:nums){
            top.add(value);
            if(top.size()>3)top.pollFirst();
        }
        return top.size()==3?top.first():top.last();
    }
}

code.kotlin:
class Solution {
    fun thirdMax(nums:IntArray):Int{
        val top=java.util.TreeSet<Int>();
        for(value in nums){
            top.add(value);
            if(top.size>3)top.pollFirst()
        };
        return if(top.size==3)top.first() else top.last()
    }
}

code.cpp:
class Solution {
    public: int thirdMax(vector<int>& nums){
        set<int> top;
        for(int value:nums){
            top.insert(value);
            if(top.size()>3)top.erase(top.begin());
        }
        return top.size()==3?*top.begin():*top.rbegin();
    }
};
